"""Offline tests use generated bytes, never customer files or SDK outputs."""
from copy import deepcopy
from hashlib import sha256
from io import BytesIO
from pathlib import Path
from tempfile import TemporaryDirectory
import unittest
from zipfile import ZipFile

from openpyxl import Workbook, load_workbook
from sanzo_demo.files import validate_original, excel_preview, original_path
from sanzo_demo.export import workbook_bytes


class FileAndExportTests(unittest.TestCase):
    def setUp(self):
        self.tmp = TemporaryDirectory()
        self.root = Path(self.tmp.name)
        self.path = self.root / "generated.xlsx"
        book = Workbook()
        book.active.append(["<script>alert(1)</script>", "=1+1", "合成プレビュー"])
        book.save(self.path)
        book.close()

    def tearDown(self):
        self.tmp.cleanup()

    def test_real_excel_preview_escapes_html_and_does_not_evaluate_formula(self):
        validate_original(self.path, ".xlsx")
        html = excel_preview(self.path, "<original>.xlsx")
        self.assertIn("&lt;script&gt;", html)
        self.assertNotIn("<script>", html)
        self.assertIn("=1+1", html)
        self.assertIn("SDK", html)

    def test_original_requires_same_hash_and_no_symlink(self):
        raw = self.path.read_bytes()
        doc = {"storage_key": self.path.name, "sha256": sha256(raw).hexdigest(), "size_bytes": len(raw)}
        self.assertEqual(original_path(self.root, doc), self.path.resolve())
        with self.path.open("ab") as handle:
            handle.write(b"changed")
        with self.assertRaises(ValueError):
            original_path(self.root, doc)
        link = self.root / "link.xlsx"
        link.symlink_to(self.path)
        with self.assertRaises(ValueError):
            original_path(self.root, {**doc, "storage_key": link.name})
        with self.assertRaises(ValueError):
            original_path(self.root, {**doc, "storage_key": "../generated.xlsx"})

    def test_extension_signature_and_zip_paths_fail_closed(self):
        with self.assertRaises(ValueError):
            validate_original(self.path, ".xlsm")
        wrong = self.root / "bad.pdf"
        wrong.write_bytes(b"not a pdf")
        with self.assertRaises(ValueError):
            validate_original(wrong, ".pdf")
        archive = self.root / "unsafe.xlsx"
        with ZipFile(archive, "w") as z:
            z.writestr("../escape", "no")
        with self.assertRaises(ValueError):
            validate_original(archive, ".xlsx")

    def test_export_preserves_duplicates_currency_exact_price_and_literal_text(self):
        base = {
            "item_id": "i1", "current_fee_id": "f1", "current_fee_name": "=2+2",
            "current_price": "12345678901234567890.1234567890", "currency": "USD",
            "version": 2, "saved_status": "HUMAN_CONFIRMED", "input_kind": "MANUAL_CONFIRMED",
            "initial_classification": {"memory_version": 4},
            "observation": {"document_id": "d1", "forwarder_id": "A", "raw_label": "@raw",
                "context": {"transport_mode": "SEA", "equipment": "20FT", "billing_unit": "CNTR",
                            "charge_scope": "IMPORT", "extra_terms": "N/A", "ready": True}},
        }
        duplicate = deepcopy(base)
        duplicate.update(item_id="i2", current_price="20", currency="JPY")
        raw = workbook_bytes({"name": "=malicious", "case_revision": 4},
                             [base, duplicate], [{"document_id": "d1", "original_filename": "=file.xlsx", "sha256": "f"*64}])
        book = load_workbook(BytesIO(raw), data_only=False)
        try:
            details = list(book["明細と出典"].iter_rows())
            self.assertEqual(details[1][4].value, base["current_price"])
            self.assertEqual(details[1][4].data_type, "s")
            self.assertEqual(details[1][3].value, "=2+2")
            self.assertEqual(details[1][3].data_type, "s")
            compare = book["原価単価一覧表"]["B4"].value
            self.assertIn(base["current_price"] + " USD", compare)
            self.assertIn("20 JPY", compare)
            self.assertEqual(book["原価単価一覧表"]["B1"].data_type, "s")
            self.assertIn("DRAFT", book["原価単価一覧表"]["A2"].value)
            self.assertIn("未確認事項", book.sheetnames)
        finally:
            book.close()

    def test_same_confirmed_id_displays_together_without_confirming_unknown_conditions(self):
        items = []
        for item_id in ["one", "two"]:
            items.append({"item_id": item_id, "current_fee_id": "f", "current_fee_name": "fee",
                "current_price": "10", "currency": "JPY", "version": 1,
                "input_kind": "MANUAL_CONFIRMED", "saved_status": "REVIEW_REQUIRED",
                "initial_classification": None,
                "observation": {"document_id": "d", "forwarder_id": "A", "raw_label": "x",
                    "context": {k: None for k in ("transport_mode", "equipment", "billing_unit", "charge_scope", "extra_terms")}}})
        book = load_workbook(BytesIO(workbook_bytes({"name": "case", "case_revision": 1}, items, [])))
        try:
            self.assertEqual(book["原価単価一覧表"].max_row, 4)
            self.assertEqual(book["原価単価一覧表"]["B4"].value.count("10 JPY"), 2)
            self.assertNotIn("確認必要", book["原価単価一覧表"]["B4"].value)
            self.assertIn("REVIEW_REQUIRED", str(list(book["明細と出典"].values)))
            self.assertTrue(all(i["saved_status"] == "REVIEW_REQUIRED" for i in items))
        finally:
            book.close()


if __name__ == "__main__":
    unittest.main(verbosity=2)
